True def transform(grid):
    n = len(grid[0])
    center = grid[0].index(2)
    out = [[0 for _ in range(n)] for _ in range(n)]
    last_radius = min(center, n - 1 - center)
    for r in range(n):
        left, right = center - r, center + r
        if 0 <= left < n:
            out[r][left] = 2
        if 0 <= right < n:
            out[r][right] = 2
        if r >= 3:
            x = (center + r) % 4
            for col in range(x, n, 4):
                if r > last_radius or left < col < right:
                    if out[r][col] == 0:
                        out[r][col] = 1
    return out
